 [tr('Financeiro e participante: comprar','Finance and participant: purchase'),tr('Preparar carteira e pedido; obter aceite do valor; executar compra de teste. O recibo do portal pertence ao Anvil.','Prepare wallet and order; obtain acceptance of the amount; execute a test purchase. The portal receipt belongs to Anvil.')],
