 [tr('Recuperação e tempo','Recovery and time'),tr('Migração preserva pesos ainda não apurados, recebíveis e pagamentos históricos sem contar o mesmo tempo duas vezes.','Migration preserves unreported weights, receivables and historical payments without counting time twice.')],
 [tr('Calendário real','Civil calendar'),tr('Testes cobrem aniversário de 29 de fevereiro e bloqueio de compras após quatro anos. Datas de teste não anunciam abertura real do Glamping.','Tests cover a 29 February anniversary and purchase rejection after four years. Test dates do not announce the real Glamping opening.')]
